    sign = "-" if cents < 0 else ""
    cents = abs(int(cents))
    return "%s%d.%02d" % (sign, cents // 100, cents % 100)


def sum_cents(values):
    """Sum an iterable of integer cent amounts."""
    total = 0
    for value in values:
        total += int(value)
    return total

